/** Live provider-directory lookup used by the generic model settings plugin. */

import type { Context } from '@deepseek-ai/cordis'
import { credentialRef } from '@deepseek-ai/dsh-credentials'
import type { CredentialProvider } from '@deepseek-ai/dsh-credentials'
import type { LlmDiscoveredModel, LlmModelDiscoveryRequest, LlmRuntime } from '@deepseek-ai/dsh-llm'
import type { SettingsProvider } from '@deepseek-ai/dsh-settings'

/** OpenAI-compatible protocols expose the common `/models` listing shape. */
const LISTABLE_PROTOCOLS: ReadonlySet<string> = new Set([
  'openai-completions',
  'openai-responses',
])

/** Bound a provider response so a broken endpoint cannot grow the host heap. */
const MAX_RESPONSE_BYTES = 4 * 1024 * 1024

interface ListingEntry {
  id?: unknown
  name?: unknown
  display_name?: unknown
  context_window?: unknown
  context_length?: unknown
  max_tokens?: unknown
  max_output_tokens?: unknown
}

interface ListingBody {
  data?: unknown
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function textField(...values: readonly unknown[]): string | undefined {
  for (const value of values) {
    if (typeof value === 'string' && value.length > 0) return value
  }
  return undefined
}

function capacity(...values: readonly unknown[]): number | undefined {
  for (const value of values) {
    if (typeof value === 'number' && Number.isInteger(value) && value > 0) return value
  }
  return undefined
}

function listingUrl(baseURL: string): string {
  return `${baseURL.replace(/\/+$/u, '')}/models`
}

async function readBounded(response: Response): Promise<string | undefined> {
  const declared = Number(response.headers.get('content-length') ?? Number.NaN)
  if (Number.isFinite(declared) && declared > MAX_RESPONSE_BYTES) {
    await response.body?.cancel()
    return undefined
  }
  if (response.body === null) return ''
  const reader = response.body.getReader()
  const chunks: Uint8Array[] = []
  let total = 0
  try {
    for (;;) {
      const { done, value } = await reader.read()
      if (done) break
      total += value.byteLength
      if (total > MAX_RESPONSE_BYTES) return undefined
      chunks.push(value)
    }
  } catch {
    return undefined
  } finally {
    await reader.cancel().catch(() => undefined)
  }
  const body = new Uint8Array(total)
  let offset = 0
  for (const chunk of chunks) {
    body.set(chunk, offset)
    offset += chunk.byteLength
  }
  return new TextDecoder().decode(body)
}

function parseListing(body: unknown): readonly LlmDiscoveredModel[] | undefined {
  const data = (isRecord(body) ? body : {})['data']
  if (!Array.isArray(data)) return undefined
  const models: LlmDiscoveredModel[] = []
  for (const raw of data) {
    if (!isRecord(raw)) continue
    const entry = raw as ListingEntry
    const id = textField(entry.id)
    if (id === undefined) continue
    const name = textField(entry.name, entry.display_name)
    const contextWindow = capacity(entry.context_window, entry.context_length)
    const maxTokens = capacity(entry.max_output_tokens, entry.max_tokens)
    models.push({
      id,
      ...name === undefined ? {} : { name },
      ...contextWindow === undefined ? {} : { contextWindow },
      ...maxTokens === undefined ? {} : { maxTokens },
    })
  }
  return models
}

/** Read the model route's credential reference from the registered settings. */
function credentialReference(
  settings: SettingsProvider,
  settingsNs: string,
  provider: string | undefined,
): string | undefined {
  const service = settings as unknown as { get(namespace: string): unknown }
  const section = service.get(settingsNs)
  if (!isRecord(section)) return undefined
  const profile = provider !== undefined && isRecord(section['providers'])
    ? section['providers'][provider]
    : section
  if (!isRecord(profile)) return undefined
  const reference = profile['apiKeyEnv']
  return typeof reference === 'string' && reference.length > 0 ? reference : undefined
}

async function storedApiKey(
  settings: SettingsProvider,
  credentials: CredentialProvider,
  settingsNs: string,
  provider: string | undefined,
): Promise<string | undefined> {
  const reference = credentialReference(settings, settingsNs, provider)
  if (reference === undefined) return undefined
  try {
    return (await credentials.resolve(credentialRef(reference)))?.value
  } catch {
    return undefined
  }
}

/**
 * Ask one draft route for its current provider directory. `undefined` means
 * the live source was unavailable, so the caller may use the official static
 * catalog as a fallback.
 */
export async function discoverLiveModels(
  settings: SettingsProvider,
  credentials: CredentialProvider,
  settingsNs: string,
  request: LlmModelDiscoveryRequest,
): Promise<readonly LlmDiscoveredModel[] | undefined> {
  if (request.baseURL === undefined || request.baseURL.length === 0) return undefined
  const api = request.api ?? 'openai-completions'
  if (!LISTABLE_PROTOCOLS.has(api)) return undefined
  const apiKey = request.apiKey ?? await storedApiKey(settings, credentials, settingsNs, request.provider)
  const headers: Record<string, string> = { accept: 'application/json' }
  if (apiKey !== undefined && apiKey.trim().length > 0) {
    // Keep the key in the host-side request only; it never enters the reply.
    headers['authorization'] = `Bearer ${apiKey.trim()}`
  }
  let response: Response
  try {
    response = await fetch(listingUrl(request.baseURL), {
      method: 'GET',
      headers,
      ...request.signal === undefined ? {} : { signal: request.signal },
    })
  } catch {
    return undefined
  }
  if (!response.ok) return undefined
  const text = await readBounded(response)
  if (text === undefined) return undefined
  try {
    return parseListing(JSON.parse(text))
  } catch {
    return undefined
  }
}

/** Install the live-first behavior without changing the official LLM runtime. */
export function installLiveModelDiscovery(ctx: Context): void {
  ctx.inject(['llm', 'settings', 'credentials'], (services) => {
    const llm = services.llm as LlmRuntime
    const original = llm.discoverModels
    const wrapped: typeof original = async function (settingsNs, request) {
      const live = await discoverLiveModels(services.settings, services.credentials, settingsNs, request)
      if (live !== undefined) return [...live]
      return original.call(llm, settingsNs, request)
    }
    llm.discoverModels = wrapped
    services.effect(() => () => {
      if (llm.discoverModels === wrapped) llm.discoverModels = original
    }, 'dsh-model-settings: live model discovery')
  })
}
